SELECT *, SUM(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_sum_90d, SUM(duration_sec) OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, LAST_VALUE(page) IGNORE NULLS OVER (ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_page, RANK() OVER (PARTITION BY event_type, session_id ORDER BY duration_sec DESC NULLS LAST) AS duration_sec_rank, NTILE(3) OVER (PARTITION BY event_type, page ORDER BY duration_sec DESC, id) AS duration_sec_bucket FROM web_events
